bool GreaterThanOrEquals(ItemIndex a, ItemIndex b) { return LessThanOrEquals(b, a); }

ItemIndex Lesser(ItemIndex a, ItemIndex b) { return (LessThanOrEquals(a, b) ? a : b); }

ItemIndex Greater(ItemIndex a, ItemIndex b) { return (LessThanOrEquals(a, b) ? b : a); }

bool Between(ItemIndex x, ItemIndex lower, ItemIndex upper) { return (LessThanOrEquals(lower, x) ? LessThanOrEquals(x, upper) : false); }

ItemIndex Clamp(ItemIndex x, ItemIndex lower, ItemIndex upper) { return Lesser(Greater(x, lower), upper); }

ItemIndex Min3(ItemIndex a, ItemIndex b, ItemIndex c) { return Lesser(Lesser(a, b), c); }

ItemIndex Max3(ItemIndex a, ItemIndex b, ItemIndex c) { return Greater(Greater(a, b), c); }

int32_t Compare(ItemIndex a, ItemIndex b) { return ((a == b) ? 0 : (LessThanOrEquals(a, b) ? (-1) : 1)); }

bool IsNone(ItemIndex self) { return ((self.Value <= 0) ? (!(self.Value == 0)) : false); }

bool IsPresent(ItemIndex self) { return (0 <= self.Value); }

int32_t Hash(ItemIndex self) { return Hash(self.Value); }

bool LessThanOrEquals(ItemIndex a, ItemIndex b) { return (a.Value <= b.Value); }

bool LessThanOrEquals(Cardinal a, Cardinal b) { return (a.Value <= b.Value); }

bool LessThan(Cardinal a, Cardinal b) { return (LessThanOrEquals(a, b) ? (a != b) : false); }

bool GreaterThan(Cardinal a, Cardinal b) { return LessThan(b, a); }

bool GreaterThanOrEquals(Cardinal a, Cardinal b) { return LessThanOrEquals(b, a); }

Cardinal Lesser(Cardinal a, Cardinal b) { return (LessThanOrEquals(a, b) ? a : b); }

Cardinal Greater(Cardinal a, Cardinal b) { return (LessThanOrEquals(a, b) ? b : a); }

bool Between(Cardinal x, Cardinal lower, Cardinal upper) { return (LessThanOrEquals(lower, x) ? LessThanOrEquals(x, upper) : false); }

Cardinal Clamp(Cardinal x, Cardinal lower, Cardinal upper) { return Lesser(Greater(x, lower), upper); }

Cardinal Min3(Cardinal a, Cardinal b, Cardinal c) { return Lesser(Lesser(a, b), c); }

Cardinal Max3(Cardinal a, Cardinal b, Cardinal c) { return Greater(Greater(a, b), c); }

int32_t Compare(Cardinal a, Cardinal b) { return ((a == b) ? 0 : (LessThanOrEquals(a, b) ? (-1) : 1)); }

DualNumber Add(DualNumber a, DualNumber b) { return DualNumber{ (a.Value + b.Value), (a.Derivative + b.Derivative) }; }

DualNumber Subtract(DualNumber a, DualNumber b) { return DualNumber{ (a.Value - b.Value), (a.Derivative - b.Derivative) }; }

DualNumber Negative(DualNumber x) { return DualNumber{ (-x.Value), (-x.Derivative) }; }

DualNumber Zero(DualNumber _) { return DualNumber{ 0.0, 0.0 }; }

DualNumber Multiply(DualNumber a, DualNumber b) { return DualNumber{ (a.Value * b.Value), ((a.Derivative * b.Value) + (a.Value * b.Derivative)) }; }

DualNumber Multiply(DualNumber x, double scalar) { return DualNumber{ (x.Value * scalar), (x.Derivative * scalar) }; }

DualNumber Divide(DualNumber a, DualNumber b) { return DualNumber{ (a.Value / b.Value), (((a.Derivative * b.Value) - (a.Value * b.Derivative)) / (b.Value * b.Value)) }; }

DualNumber Divide(DualNumber x, double scalar) { return DualNumber{ (x.Value / scalar), (x.Derivative / scalar) }; }

DualNumber Modulo(DualNumber x, double scalar) { return DualNumber{ fmodf(x.Value, scalar), x.Derivative }; }

